def glob_to_regex(glob: str, word_boundary: bool = False) -> Pattern:
    """Converts a glob to a compiled regex object.
    Args:
        glob: pattern to match
        word_boundary: If True, the pattern will be allowed to match at word boundaries
           anywhere in the string. Otherwise, the pattern is anchored at the start and
           end of the string.
    Returns:
        compiled regex pattern
    """
    chunks = []
    for chunk in _WILDCARD_RUN.split(glob):
        if not _WILDCARD_RUN.match(chunk):
            chunks.append(re.escape(chunk))
            continue
        qmarks = chunk.count("?")
        if "*" in chunk:
            chunks.append(".{%d,}" % qmarks)
        else:
            chunks.append(".{%d}" % qmarks)
    res = "".join(chunks)
    if word_boundary:
        res = re_word_boundary(res)
    else:
        res = r"\A" + res + r"\Z"
    return re.compile(res, re.IGNORECASE)
def run_as_background_process(desc: str, func, *args, bg_start_span=True, **kwargs):
    async def run():
        with _bg_metrics_lock:
            count = _background_process_counts.get(desc, 0)
            _background_process_counts[desc] = count + 1
        _background_process_start_count.labels(desc).inc()
        _background_process_in_flight_count.labels(desc).inc()
        with BackgroundProcessLoggingContext(desc, count) as context:
            try:
                ctx = noop_context_manager()
                if bg_start_span:
                    ctx = start_active_span(desc, tags={"request_id": str(context)})
                with ctx:
                    return await maybe_awaitable(func(*args, **kwargs))
            except Exception:
                logger.exception(
                    "Background process '%s' threw an exception",
                    desc,
                )
            finally:
                _background_process_in_flight_count.labels(desc).dec()
