        """
        Returns True if the image is hosted on the local filesystem
        """
        try:
            self.file.path
            return True
        except NotImplementedError:
            return False
    @contextmanager
    def open_file(self):
        close_file = False
        f = self.file
        if f.closed:
            if self.is_stored_locally():
                f.open("rb")
            else:
                storage = self._meta.get_field("file").storage
                f = storage.open(f.name, "rb")
            close_file = True
        f.seek(0)
        try:
            yield f
        finally:
            if close_file:
                f.close()
    def _set_file_hash(self, file_contents):
        self.file_hash = hashlib.sha1(file_contents).hexdigest()
    def get_file_hash(self):
        if self.file_hash == "":
            with self.open_file() as f:
                self._set_file_hash(f.read())
            self.save(update_fields=["file_hash"])
        return self.file_hash
    def _set_document_file_metadata(self):
        self.file.open()
        self.file_size = self.file.size
        self._set_file_hash(self.file.read())
        self.file.seek(0)
    @property
    def filename(self):
        return os.path.basename(self.file.name)
    @property
    def url(self):
        if getattr(settings, "WAGTAILDOCS_SERVE_METHOD", None) == "direct":
            try:
                return self.file.url
            except NotImplementedError:
                pass
        return reverse("wagtaildocs_serve", args=[self.id, self.filename])

