                num_entries += 1
                if limit is not None and num_entries >= limit:
                    break
        with open(index, 'r') as f:
            yield '<?xml version="1.0" encoding="UTF-8" ?>\n'
            if STYLE:
                yield '<?xml-stylesheet type="text/xsl" href="/scopelist.xsl" ?>\n'
